"""## 3. Data Preprocessing

Convert the raw drawing data into a format suitable for CNN training
"""

def preprocess_drawings(data, img_size=(28, 28)):
    """
    Preprocess QuickDraw drawings for CNN training
    """
    # Normalize pixel values to [0, 1]
    data = data.astype('float32') / 255.0

    # Reshape to image format
    data = data.reshape(-1, img_size[0], img_size[1], 1)

    return data

# Preprocess all categories
processed_data = {}
for category, data in dataset.items():
    processed_data[category] = preprocess_drawings(data)
    print(f"Preprocessed {category}: {processed_data[category].shape}")

# Combine all data and create labels
X = np.concatenate([processed_data[cat] for cat in CATEGORIES])
y = np.concatenate([[i] * len(processed_data[cat]) for i, cat in enumerate(CATEGORIES)])

