"""## 6. Build CNN Model

Based on the original model architecture that achieved 90% accuracy
"""

import tensorflow as tf
from tensorflow import keras
from tensorflow.keras import layers

def residual_block(x, filters, stride=1):
    """
    A residual block for ResNet-18.
    """
    shortcut = x

    # First convolution
    x = layers.Conv2D(filters, (3, 3), strides=stride, padding='same')(x)
    x = layers.BatchNormalization()(x)
    x = layers.Activation('relu')(x)

    # Second convolution
    x = layers.Conv2D(filters, (3, 3), strides=1, padding='same')(x)
    x = layers.BatchNormalization()(x)

    # Shortcut connection to match dimensions
    if stride != 1:
        shortcut = layers.Conv2D(filters, (1, 1), strides=stride, padding='same')(shortcut)
        shortcut = layers.BatchNormalization()(shortcut)

    # Add the shortcut to the main path
    x = layers.add([x, shortcut])
    x = layers.Activation('relu')(x)

    return x

def build_cnn_model(input_shape=(28, 28, 1), num_classes=50):
    """
    Build a ResNet-18 model for classification.
    """
    inputs = layers.Input(shape=input_shape)

    # --- Adaptation for Grayscale Input ---
    # Standard ResNet-18 expects 3-channel images. We add a 1x1 conv to
    # convert the 1-channel grayscale input to 3 channels.
    x = layers.Conv2D(3, (1, 1), padding='same')(inputs)

    # --- Initial Convolution and Pooling ---
    # Standard ResNet start
    x = layers.Conv2D(64, (7, 7), strides=2, padding='same')(x)
    x = layers.BatchNormalization()(x)
    x = layers.Activation('relu')(x)
    x = layers.MaxPooling2D((3, 3), strides=2, padding='same')(x)

    # --- ResNet-18 Stages ---
    # Stage 1: 2 residual blocks, 64 filters
    x = residual_block(x, 64, stride=1)
    x = residual_block(x, 64, stride=1)

    # Stage 2: 2 residual blocks, 128 filters (downsampling)
    x = residual_block(x, 128, stride=2)
    x = residual_block(x, 128, stride=1)

    # Stage 3: 2 residual blocks, 256 filters (downsampling)
    x = residual_block(x, 256, stride=2)
    x = residual_block(x, 256, stride=1)

    # Stage 4: 2 residual blocks, 512 filters (downsampling)
    x = residual_block(x, 512, stride=2)
    x = residual_block(x, 512, stride=1)

    # --- Model Head ---
    # Use Global Average Pooling instead of Flatten + Dense layers
    x = layers.GlobalAveragePooling2D()(x)

    # Output layer
    outputs = layers.Dense(num_classes, activation='softmax')(x)

    # Create the model
    model = keras.Model(inputs=inputs, outputs=outputs)

    # --- Compile Model ---
    # Kept the same compilation settings as your original model
    initial_learning_rate = 0.001
    optimizer = keras.optimizers.Adam(learning_rate=initial_learning_rate)

    model.compile(
        optimizer=optimizer,
        loss='categorical_crossentropy',
        metrics=['accuracy', 'top_k_categorical_accuracy']
    )

    return model

# Build the model
model = build_cnn_model()
model.summary()

