def predict_drawing(model, drawing, categories):
    """
    Make prediction on a single drawing
    """
    # Preprocess
    # drawing = drawing.astype('float32') / 255.0
    drawing = drawing.reshape(1, 28, 28, 1)

    # Predict
    prediction = model.predict(drawing, verbose=0)[0]
    predicted_class = np.argmax(prediction)
    confidence = prediction[predicted_class]

    output_predictions = [(cls, prob) for cls in CATEGORIES for prob in prediction]

    return categories[predicted_class], confidence

